import React, { useState, useEffect } from 'react';
import { XCircleIcon, ChevronRightIcon } from '@heroicons/react/24/solid';
import { fetchJavelinDataByDate } from '../../services/api';

// A single selectable throw item in the list
const ThrowItem = ({ date, throwData, index, isChecked, onThrowChange }) => (
  <label className="flex items-center p-2 rounded-md hover:bg-gray-100 cursor-pointer pl-4">
    <input
      type="checkbox"
      className="h-4 w-4 accent-blue-500 rounded mr-3 flex-shrink-0"
      checked={isChecked}
      onChange={() => onThrowChange(date, index)}
    />
    <div className="flex items-baseline whitespace-nowrap text-sm">
      <span className="mr-2">{`Throw ${index + 1}`}</span>
      <span className="text-gray-500 mr-3">({throwData.time})</span>
      <span className="font-semibold text-gray-700 bg-gray-200 px-1.5 py-0.5 rounded">
        {throwData.playerStats.range}m
      </span>
    </div>
  </label>
);

// A collapsible section for a single date
const DateSection = ({ date, throws, selectedThrows, onThrowChange, isOpen, onToggle }) => {
  const formatDate = (dateStr) => {
    const [year, month, day] = dateStr.split('-');
    return `${month}/${day}/${year}`;
  };

  return (
    <div className="border-b border-gray-200 last:border-b-0">
      <button
        onClick={() => onToggle(date)}
        className="w-full flex items-center justify-between p-2 text-left hover:bg-gray-50"
      >
        <h3 className="font-bold text-md text-gray-800">
          {formatDate(date)}
        </h3>
        <ChevronRightIcon
          className={`h-5 w-5 text-gray-500 transform transition-transform ${
            isOpen ? 'rotate-90' : ''
          }`}
        />
      </button>
      {isOpen && (
        <div className="py-2 space-y-1">
          {throws.map((throwData, index) => (
            <ThrowItem
              key={index}
              date={date}
              throwData={throwData}
              index={index}
              isChecked={selectedThrows[date]?.includes(index) ?? false}
              onThrowChange={onThrowChange}
            />
          ))}
        </div>
      )}
    </div>
  );
};

// Main component to replace the calendar filter
const CalendarFilter = ({
  availableDates = [],
  selectedThrows = {},
  onChange = () => {},
  onReset = () => {},
}) => {
  const [allThrowsData, setAllThrowsData] = useState({});
  const [isLoading, setIsLoading] = useState(true);
  const [openSections, setOpenSections] = useState({}); // State to manage accordion

  // Fetch all throw details for every available date
  useEffect(() => {
    const fetchAllThrows = async () => {
      if (availableDates.length === 0) {
        setIsLoading(false);
        return;
      }
      setIsLoading(true);
      try {
        const promises = availableDates.map(d => fetchJavelinDataByDate(d.value));
        const results = await Promise.all(promises);
        const throwsByDate = {};
        availableDates.forEach((dateInfo, index) => {
          throwsByDate[dateInfo.value] = results[index].throws;
        });
        setAllThrowsData(throwsByDate);
      } catch (error) {
        console.error("Failed to fetch all throw data:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchAllThrows();
  }, [availableDates]);

  // Handler for checkbox changes
  const handleThrowCheckboxChange = (dateStr, throwIndex) => {
    const newSelection = JSON.parse(JSON.stringify(selectedThrows));
    const dateSelections = newSelection[dateStr] || [];
    if (dateSelections.includes(throwIndex)) {
      newSelection[dateStr] = dateSelections.filter(i => i !== throwIndex);
      if (newSelection[dateStr].length === 0) delete newSelection[dateStr];
    } else {
      newSelection[dateStr] = [...dateSelections, throwIndex].sort((a, b) => a - b);
    }
    onChange(newSelection);
  };
  
  // Handler to toggle the accordion sections
  const handleToggleSection = (date) => {
    setOpenSections(prev => ({
      ...prev,
      [date]: !prev[date],
    }));
  };

  const totalSelectedCount = Object.values(selectedThrows).reduce((acc, throws) => acc + throws.length, 0);

  return (
    <div className="h-full flex flex-col">
      <div className="flex justify-between items-center mb-4 flex-shrink-0">
        <label className="block text-lg font-bold text-gray-800">
          Select Throws
        </label>
        <button
          onClick={onReset}
          disabled={totalSelectedCount === 0}
          className="p-2 bg-red-500 text-white rounded-md shadow-sm transition-all hover:bg-red-600 disabled:opacity-40 disabled:cursor-not-allowed"
          aria-label="Reset selections"
        >
          <XCircleIcon className="h-5 w-5" />
        </button>
      </div>

      <div className="flex-1 border border-gray-200 rounded-lg overflow-y-auto">
        {isLoading ? (
          <p className="p-4 text-center text-gray-500">Loading throws...</p>
        ) : Object.keys(allThrowsData).length > 0 ? (
          <div>
            {Object.keys(allThrowsData).map(date => (
              <DateSection
                key={date}
                date={date}
                throws={allThrowsData[date]}
                selectedThrows={selectedThrows}
                onThrowChange={handleThrowCheckboxChange}
                isOpen={!!openSections[date]}
                onToggle={handleToggleSection}
              />
            ))}
          </div>
        ) : (
          <p className="p-4 text-center text-gray-500">No throws available.</p>
        )}
      </div>
    </div>
  );
};

export default CalendarFilter;
